#include <stdio.h>

// Function demonstrating bitwise operators
int bitwise_operations_example(int a, int b) {
    // Left shift: shifts bits to the left (a << b = a * 2^b)
    int left_shift = a << b;

    // Right shift: shifts bits to the right (a >> b = a / 2^b for positive numbers)
    int right_shift = a >> b;

    // Bitwise OR: sets each bit to 1 if at least one of the corresponding bits is 1
    int bitwise_or = a | b;

    // Bitwise AND: sets each bit to 1 if both corresponding bits are 1
    int bitwise_and = a & b;

    printf("a = %d (binary: %s)\n", a, __builtin_clz(a) ? 
           __builtin_clz(a) == 31 ? "00000000000000000000000000000001" : 
           __builtin_clz(a) == 30 ? "00000000000000000000000000000010" : 
           "other");
    printf("b = %d (binary representation would be complex to print dynamically)\n", b);
    printf("a << b = %d\n", left_shift);
    printf("a >> b = %d\n", right_shift);
    printf("a | b = %d\n", bitwise_or);
    printf("a & b = %d\n", bitwise_and);

    return bitwise_or;
}

// Example of using pipe operator in a shell command
void shell_pipe_example() {
    // In a shell command, | is used to pipe output from one command to another
    // Example: ls -l | grep ".txt" lists files and filters for .txt files
    system("echo 'Hello World' | tr 'a-z' 'A-Z'"); // Pipes output to uppercase converter
}

int main() {
    int a = 8;  // binary: 1000
    int b = 2;  // binary: 0010

    printf("Bitwise Operations Example:\n");
    bitwise_operations_example(a, b);

    printf("\nShell Pipe Example:\n");
    shell_pipe_example();

    return 0;
}
```

This code demonstrates the requested bitwise operators:
- `<<` (left shift): shifts bits left, multiplying by powers of 2
- `>>` (right shift): shifts bits right, dividing by powers of 2
- `|` (bitwise OR): combines bits where at least one is 1
- `&` (bitwise AND): keeps only bits that are 1 in both operands

The shell pipe example shows how the pipe operator `|` is used in shell commands to connect the output of one command (like `echo`) to the input of another (like `tr` to transform text).

