<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Product Listing</title>
    <style>
        body { font-family: Arial, sans-serif; margin: 0; padding: 20px; }
        .container { max-width: 1200px; margin: 0 auto; }
        h1 { text-align: center; color: #333; }
        .product-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 20px; }
        .product-card { border: 1px solid #ddd; border-radius: 8px; overflow: hidden; transition: transform 0.2s; }
        .product-card:hover { transform: translateY(-5px); box-shadow: 0 5px 15px rgba(0,0,0,0.1); }
        .product-image { width: 100%; height: 200px; object-fit: cover; background-color: #f5f5f5; }
        .product-info { padding: 15px; }
        .product-title { font-size: 1.2rem; margin: 0 0 10px; color: #333; }
        .product-price { font-size: 1.4rem; font-weight: bold; color: #e63946; margin: 10px 0; }
        .product-description { color: #666; font-size: 0.9rem; margin-bottom: 15px; }
        .product-tags { display: flex; flex-wrap: wrap; gap: 5px; margin-bottom: 15px; }
        .tag { background-color: #e9ecef; padding: 3px 8px; border-radius: 15px; font-size: 0.8rem; }
        .availability { font-size: 0.9rem; margin-bottom: 15px; }
        .in-stock { color: #2a9d8f; }
        .out-of-stock { color: #e63946; }
        .btn { display: inline-block; padding: 10px 20px; background-color: #457b9d; color: white; text-decoration: none; border-radius: 5px; transition: background-color 0.2s; }
        .btn:hover { background-color: #1d3557; }
        .btn:disabled { background-color: #ccc; cursor: not-allowed; }
        .no-products { text-align: center; padding: 40px; color: #666; }
    </style>
</head>
<body>
    <div class="container">
        <h1>{{ page_title }}</h1>

        {% if products %}
        <div class="product-grid">
            {% for product in products %}
            <div class="product-card">
                {% if product.image %}
                <img src="{{ product.image }}" alt="{{ product.name }}" class="product-image">
                {% else %}
                <div class="product-image" style="display: flex; align-items: center; justify-content: center;">
                    <span style="color: #aaa;">No Image</span>
                </div>
                {% endif %}

                <div class="product-info">
                    <h2 class="product-title">{{ product.name }}</h2>
                    <div class="product-price">${{ "%.2f"|format(product.price) }}</div>
                    <p class="product-description">{{ product.description[:150] }}{% if product.description|length > 150 %}...{% endif %}</p>

                    {% if product.tags %}
                    <div class="product-tags">
                        {% for tag in product.tags %}
                        <span class="tag">{{ tag }}</span>
                        {% endfor %}
                    </div>
                    {% endif %}

                    <div class="availability">
                        {% if product.in_stock %}
                        <span class="in-stock">In Stock ({{ product.stock_quantity }} units)</span>
                        {% else %}
                        <span class="out-of-stock">Out of Stock</span>
                        {% endif %}
                    </div>

                    <a href="{{ product.url }}" class="btn" {% if not product.in_stock %}disabled{% endif %}>
                        {% if product.in_stock %}Add to Cart{% else %}Notify When Available{% endif %}
                    </a>
                </div>
            </div>
            {% endfor %}
        </div>
        {% else %}
        <div class="no-products">
            <p>No products available at this time.</p>
        </div>
        {% endif %}

        {% if show_filters %}
        <div class="filters" style="margin-top: 30px; padding: 15px; background: #f9f9f9; border-radius: 8px;">
